package com.bank.flink.cep;

// A keyed authentication/payment action for an account.
class AuthEvent {
    enum Action { LOGIN, FAILED_PAYMENT, LOGOUT, OTHER }

    private final String accountId;
    private final Action action;
    private final long eventTimeMillis;

    AuthEvent(String accountId, Action action, long eventTimeMillis) {
        this.accountId = accountId;
        this.action = action;
        this.eventTimeMillis = eventTimeMillis;
    }

    String getAccountId() { return accountId; }
    Action getAction() { return action; }
    long getEventTimeMillis() { return eventTimeMillis; }
}
