package com.bank.flink.cep;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Models the CEP NFA for: LOGIN -> FAILED_PAYMENT -> LOGOUT within 5 minutes.
class FraudPatternMatcher {
    private static final Logger log = Logger.getLogger(FraudPatternMatcher.class.getName());
    private static final long WINDOW_MS = 5L * 60 * 1000;

    // Per-account partial match: which stage reached + when the pattern started.
    private static class Partial {
        int stage;          // 0=none,1=saw LOGIN,2=saw FAILED_PAYMENT
        long startMillis;   // time of the LOGIN that began the match
    }

    private final Map<String, Partial> progress = new HashMap<>();
    private final List<String> matches = new ArrayList<>();
    private final List<String> timeouts = new ArrayList<>();

    // processElement equivalent: advance the automaton for this account.
    void onEvent(AuthEvent e) {
        String key = e.getAccountId();
        Partial p = progress.computeIfAbsent(key, k -> new Partial());

        switch (e.getAction()) {
            case LOGIN:
                p.stage = 1;
                p.startMillis = e.getEventTimeMillis();
                log.info(() -> "begin[login] " + key);
                break;
            case FAILED_PAYMENT:
                if (p.stage == 1 && within(p, e)) {
                    p.stage = 2;
                    log.info(() -> "next[failedPayment] " + key);
                } else {
                    reset(key);
                }
                break;
            case LOGOUT:
                if (p.stage == 2 && within(p, e)) {
                    String alert = "FRAUD MATCH account=" + key
                            + " login->failedPayment->logout within 5min";
                    matches.add(alert);
                    log.warning(() -> alert);
                }
                reset(key);
                break;
            default:
                // OTHER with strict next() would break the sequence.
                break;
        }
    }

    // Watermark advance: time out partial matches that exceeded the window.
    void onWatermark(long watermark) {
        for (Map.Entry<String, Partial> entry : progress.entrySet()) {
            Partial p = entry.getValue();
            if (p.stage > 0 && watermark > p.startMillis + WINDOW_MS) {
                String t = "TIMEOUT account=" + entry.getKey()
                        + " incomplete pattern (stage " + p.stage + ")";
                timeouts.add(t);
                log.info(() -> t);
            }
        }
        progress.values().removeIf(p -> p.stage > 0 && watermark > p.startMillis + WINDOW_MS);
    }

    private boolean within(Partial p, AuthEvent e) {
        return e.getEventTimeMillis() <= p.startMillis + WINDOW_MS;
    }

    private void reset(String key) { progress.remove(key); }

    List<String> getMatches() { return matches; }
    List<String> getTimeouts() { return timeouts; }
}
