package com.bank.flink.cep;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CepDemo {
    private static final Logger log = Logger.getLogger(CepDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        long min = 60L * 1000;
        FraudPatternMatcher cep = new FraudPatternMatcher();

        // Account SAV2001: full fraud sequence within 5 min -> MATCH.
        cep.onEvent(new AuthEvent("SAV2001", AuthEvent.Action.LOGIN, 0));
        cep.onEvent(new AuthEvent("SAV2001", AuthEvent.Action.FAILED_PAYMENT, 1 * min));
        cep.onEvent(new AuthEvent("SAV2001", AuthEvent.Action.LOGOUT, 3 * min));

        // Account CUR3001: login + failed payment, no logout -> TIMEOUT.
        cep.onEvent(new AuthEvent("CUR3001", AuthEvent.Action.LOGIN, 0));
        cep.onEvent(new AuthEvent("CUR3001", AuthEvent.Action.FAILED_PAYMENT, 2 * min));

        // Advance watermark past 5 minutes to trigger timeout cleanup.
        cep.onWatermark(6 * min);

        log.info("matches=" + cep.getMatches());
        log.info("timeouts=" + cep.getTimeouts());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
